public function PrefillCreationForm(&$aContextParam)
{
    parent::PrefillCreationForm($aContextParam);

    $oConf = Metamodel::GetConfig();
    $aChangeDefaults = $oConf->GetModuleSetting('br-tickettemplates', 'change_defaults', array());

    $iOrgId = $aChangeDefaults['org_id'];
    $sOrgQuery = 'SELECT Organization WHERE id = :orgid';
    $oOrgSet = new DBObjectSet(DBObjectSearch::FromOQL($sOrgQuery), array(), array('orgid' => $iOrgId));
    if ($oOrgSet->Count() > 0) {
        $oOrg = $oOrgSet->Fetch();
        $this->Set('org_id', $oOrg->Get('id'));
    }

    $sDescription = $aChangeDefaults['description'] ?? null;
    if (!empty($sDescription)) {
        $this->Set('description', $sDescription);
    }
}

