public function PrefillTransitionForm(&$aContextParam)
{
    parent::PrefillTransitionForm($aContextParam);

    if ($aContextParam['stimulus'] == 'ev_assign') {

        $oConf = Metamodel::GetConfig();
        $aChangeDefaults = $oConf->GetModuleSetting('br-tickettemplates', 'change_defaults', array());

        $iSupervisorGroupId = $aChangeDefaults['routine_change']['supervisor_group_id'] ?? $aChangeDefaults['supervisor_group_id'] ?? 0;
        if ($iSupervisorGroupId > 0) {
            $this->Set('supervisor_group_id', $iSupervisorGroupId);
            if (array_key_exists('supervisor_group_id', $aContextParam['expected_attributes'])) {
                $aContextParam['expected_attributes']['supervisor_group_id'] |= OPT_ATT_MUSTPROMPT;
            }
        }

        $iSupervisorId = $aChangeDefaults['routine_change']['supervisor_id'] ?? $aChangeDefaults['supervisor_id'] ?? 0;
        if ($iSupervisorId > 0) {
            $this->Set('supervisor_id', $iSupervisorId);
            if (array_key_exists('supervisor_id', $aContextParam['expected_attributes'])) {
                $aContextParam['expected_attributes']['supervisor_id'] |= OPT_ATT_MUSTPROMPT;
            }
        }

        $iManagerGroupId = $aChangeDefaults['routine_change']['manager_group_id'] ?? $aChangeDefaults['manager_group_id'] ?? 0;
        if ($iManagerGroupId > 0) {
            $this->Set('manager_group_id', $iManagerGroupId);
            if (array_key_exists('manager_group_id', $aContextParam['expected_attributes'])) {
                $aContextParam['expected_attributes']['manager_group_id'] |= OPT_ATT_MUSTPROMPT;
            }
        }

        $iManagerId = $aChangeDefaults['routine_change']['manager_id'] ?? $aChangeDefaults['manager_id'] ?? 0;
        if ($iManagerId > 0) {
            $this->Set('manager_id', $iManagerId);
            if (array_key_exists('manager_id', $aContextParam['expected_attributes'])) {
                $aContextParam['expected_attributes']['manager_id'] |= OPT_ATT_MUSTPROMPT;
            }
        }
    }
}

